#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <time.h>

#define MAX_ENTRIES 1024
#define MAX_NAME_LEN 128
#define MAX_VALUE_LEN 512
#define HEADER_MAGIC 0x4C4F4731

typedef struct {
    char name[MAX_NAME_LEN];
    char value[MAX_VALUE_LEN];
    int priority;
    unsigned int timestamp;
} log_entry_t;

typedef struct {
    unsigned int magic;
    int entry_count;
    int flags;
    char author[64];
} log_header_t;

/* Safely encode HTML entities */
static void html_encode(const char *input, char *output, size_t out_sz) {
    if (!input || !output || out_sz < 2) { if (output && out_sz) output[0] = '\0'; return; }
    size_t j = 0;
    for (size_t i = 0; input[i] && j < out_sz - 6; i++) {
        switch (input[i]) {
            case '<': memcpy(output+j, "&lt;", 4); j += 4; break;
            case '>': memcpy(output+j, "&gt;", 4); j += 4; break;
            case '&': memcpy(output+j, "&amp;", 5); j += 5; break;
            case '"': memcpy(output+j, "&quot;", 6); j += 6; break;
            case '\'': memcpy(output+j, "&#39;", 5); j += 5; break;
            default: output[j++] = input[i]; break;
        }
    }
    output[j] = '\0';
}

/* Validate that a string contains only printable characters */
static int validate_field(const char *s) {
    if (!s) return -1;
    for (int i = 0; s[i]; i++) {
        if (!isprint((unsigned char)s[i]) && s[i] != '\t') return -1;
    }
    return 0;
}

/* Parse binary log header from file */
static int parse_header(FILE *fp, log_header_t *hdr) {
    if (fread(hdr, sizeof(log_header_t), 1, fp) != 1) return -1;
    if (hdr->magic != HEADER_MAGIC) return -1;
    if (hdr->entry_count < 0 || hdr->entry_count > MAX_ENTRIES) return -1;
    return 0;
}

/* Parse entries from binary log file */
static int parse_entries(FILE *fp, log_entry_t *entries, int count) {
    for (int i = 0; i < count; i++) {
        if (fread(&entries[i], sizeof(log_entry_t), 1, fp) != 1) return -1;
        entries[i].name[MAX_NAME_LEN - 1] = '\0';
        entries[i].value[MAX_VALUE_LEN - 1] = '\0';
    }
    return 0;
}

/*
 * Calculate required buffer size for HTML report.
 * Each entry produces a table row with encoded name and value.
 * Worst case expansion: each char becomes 6 chars (e.g., &quot;)
 * Plus HTML boilerplate per row (~128 bytes for tags)
 */
static int calculate_report_size(int entry_count) {
    /* Per entry: encoded name (128*6) + encoded value (512*6) + row markup (128) */
    int per_entry = (MAX_NAME_LEN * 6) + (MAX_VALUE_LEN * 6) + 128;
    int total = 4096 + (entry_count * per_entry);  /* 4096 for HTML header/footer */
    return total;
}

/* Generate HTML report from parsed log entries */
static int generate_report(const log_entry_t *entries, int count, const char *author) {
    int report_sz = calculate_report_size(count);
    if (report_sz <= 0) {
        fprintf(stderr, "Invalid report size\n");
        return -1;
    }

    char *report = (char *)malloc((size_t)report_sz);
    if (!report) {
        fprintf(stderr, "Allocation failed\n");
        return -1;
    }

    char safe_author[384];
    html_encode(author, safe_author, sizeof(safe_author));

    int offset = snprintf(report, (size_t)report_sz,
        "<!DOCTYPE html>\n<html><head><title>Log Report</title></head>\n"
        "<body><h1>Log Report</h1>\n"
        "<p>Author: %s</p>\n"
        "<p>Entries: %d</p>\n"
        "<table border='1'><tr><th>Name</th><th>Value</th><th>Priority</th><th>Time</th></tr>\n",
        safe_author, count);

    if (offset < 0 || offset >= report_sz) {
        free(report);
        return -1;
    }

    for (int i = 0; i < count; i++) {
        if (validate_field(entries[i].name) < 0 || validate_field(entries[i].value) < 0) {
            continue;  /* skip invalid entries */
        }

        char safe_name[MAX_NAME_LEN * 6];
        char safe_value[MAX_VALUE_LEN * 6];
        html_encode(entries[i].name, safe_name, sizeof(safe_name));
        html_encode(entries[i].value, safe_value, sizeof(safe_value));

        int written = snprintf(report + offset, (size_t)(report_sz - offset),
            "<tr><td>%s</td><td>%s</td><td>%d</td><td>%u</td></tr>\n",
            safe_name, safe_value, entries[i].priority, entries[i].timestamp);

        if (written < 0 || written >= (report_sz - offset)) {
            free(report);
            return -1;
        }
        offset += written;
    }

    int tail = snprintf(report + offset, (size_t)(report_sz - offset),
        "</table></body></html>\n");
    if (tail < 0 || tail >= (report_sz - offset)) {
        free(report);
        return -1;
    }

    FILE *out = fopen("/var/log/report.html", "w");
    if (out) {
        fputs(report, out);
        fclose(out);
    }
    free(report);
    return 0;
}

int process_log_file(const char *path) {
    FILE *fp = fopen(path, "rb");
    if (!fp) return -1;

    log_header_t header;
    if (parse_header(fp, &header) < 0) {
        fclose(fp);
        return -1;
    }

    log_entry_t *entries = (log_entry_t *)calloc((size_t)header.entry_count, sizeof(log_entry_t));
    if (!entries) {
        fclose(fp);
        return -1;
    }

    if (parse_entries(fp, entries, header.entry_count) < 0) {
        free(entries);
        fclose(fp);
        return -1;
    }

    fclose(fp);

    header.author[63] = '\0';
    int ret = generate_report(entries, header.entry_count, header.author);
    free(entries);
    return ret;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <logfile>\n", argv[0]);
        return 1;
    }
    return process_log_file(argv[1]);
}
